<?xml version="1.0" encoding="UTF-8"?><map version="1.0.1"><node TEXT="数据整理"><node TEXT="整理基础"><node TEXT="作用"><node TEXT="原始或综合资料 → 科学分组与汇总"></node><node TEXT="系统化、条理化；反映总体特征"></node><node TEXT="建立数据库，实现一源多用"></node></node><node TEXT="基本步骤"><node TEXT="① 根据研究目的设计方案与指标"></node><node TEXT="② 审核完整性、准确性、时效性"></node><node TEXT="③ 分组汇总，计算均值、方差等"></node><node TEXT="④ 用统计表、统计图展示结果"></node><node TEXT="⑤ 积累、保管与公布统计资料"></node></node></node><node TEXT="统计分组"><node TEXT="含义与要求"><node TEXT="对总体是“分”，对个体是“合”"></node><node TEXT="组内同质，组间有差异"></node><node TEXT="穷尽：都有组可归；互斥：只归一个组"></node></node><node TEXT="作用"><node TEXT="划分现象类型；揭示内部结构"></node><node TEXT="反映总体特点和规律；分析依存关系"></node></node><node TEXT="选择标志"><node TEXT="依据研究目的"></node><node TEXT="选择反映本质特征的主要标志"></node><node TEXT="结合具体历史与经济条件动态选择"></node></node></node><node TEXT="分组方法"><node TEXT="按标志性质"><node TEXT="品质标志：性别、设备种类等"></node><node TEXT="数量标志：利用率、饱和度等"></node></node><node TEXT="分组体系"><node TEXT="平行分组：多个标志分别分组"></node><node TEXT="复合分组：多个标志依次分组"></node></node><node TEXT="分组关键"><node TEXT="选择分组标志 → 确定组数 → 划分界限"></node></node></node><node TEXT="分配数列"><node TEXT="类型"><node TEXT="品质分配数列"></node><node TEXT="变量分配数列：单项数列、组距数列"></node><node TEXT="组距数列：等距、不等距"></node></node><node TEXT="编制要点"><node TEXT="组限宜用整数，便于理解与计算"></node><node TEXT="首末组覆盖全部变量值"></node><node TEXT="无极端值时可采用闭口组"></node><node TEXT="连续型变量采用重叠式组限"></node></node><node TEXT="频数与频率"><node TEXT="频数之和＝样本量"></node><node TEXT="频率＝该组频数 ÷ 总频数"></node><node TEXT="案例：50名工人日加工零件数分组"></node></node></node><node TEXT="整理规范"><node TEXT="电子与现场数据"><node TEXT="电子数据：网络信息、通信信息、记录日志、电子文件"></node><node TEXT="现场数据：逐日、逐周核对，确保真实与代表性"></node></node><node TEXT="数据一致性"><node TEXT="统一来源、指标口径与命名"></node><node TEXT="统一单位和字段类型，补全注释"></node><node TEXT="过滤无意义数据，监控指标结果"></node><node TEXT="减少重复建设，建立统一数据公共层"></node></node><node TEXT="次级数据核查"><node TEXT="核查原收集目的、来源与统计单位"></node><node TEXT="评估可靠性、收集方法、重复与遗漏"></node><node TEXT="多来源内容不一致时，查明原因后取舍"></node></node></node></node></map>